```python
def manage_to_do_list():
    """Manage a simple to-do list using an if/else statement."""

    # Initialize an empty list to store tasks
    tasks = []

    while True:
        # Get user input
        user_input = input("Enter 'add' to add a task, 'complete' to mark a task as complete, or 'view' to view the to-do list, or 'quit' to exit: ").lower()

        # Exit the program
        if user_input == "quit":
            print("Goodbye!")
            break

        # Add a task
        elif user_input == "add":
            task_text = input("Enter the task text: ")
            tasks.append(task_text)
            print(f"Task added: {task_text}")

        # Mark a task as complete
        elif user_input == "complete":
            if tasks:
                task_index = int(input("Enter the index of the task to mark as complete (or -1 to mark the last task): ")) - 1
                if task_index >= 0 and task_index < len(tasks):
                    tasks[task_index] = f"({tasks[task_index]})"
                    print(f"Task {task_index + 1} marked as complete: {tasks[task_index]}")
                else:
                    print("Invalid task index.")
            else:
                print("To-do list is empty.")

        # View the to-do list
        elif user_input == "view":
            if tasks:
                print("To-do list:")
                for i, task in enumerate(tasks):
                    print(f"{i + 1}. {task}")
            else:
                print("To-do list is empty.")

        # Invalid input
        else:
            print("Invalid input. Please try again.")


if __name__ == "__main__":
    manage_to_do_list()
```

This program will continue to prompt the user for input until they enter "quit". You can customize the program further by adding more functionality, such as allowing users to delete tasks or sort the to-do list.
